%sh
hbase shell -n <<'HBASE_EOF'
get 'network_events', 'RTR-EDM-020#9223370253961075807#EVT-000501', {COLUMN => 'status:state'}

put 'network_events', 'RTR-EDM-020#9223370253961075807#EVT-000501', 'status:state', 'Investigating'
put 'network_events', 'RTR-EDM-020#9223370253961075807#EVT-000501', 'status:state', 'Resolved'
put 'network_events', 'RTR-EDM-020#9223370253961075807#EVT-000501', 'status:state', 'Closed'

get 'network_events', 'RTR-EDM-020#9223370253961075807#EVT-000501', {COLUMN => 'status:state'}
get 'network_events', 'RTR-EDM-020#9223370253961075807#EVT-000501', {COLUMN => 'status:state', VERSIONS => 5}

put 'network_events', 'SWT-CAL-036#9223370253955825807#EVT-000502', 'event:severity', 'Critical'
get 'network_events', 'SWT-CAL-036#9223370253955825807#EVT-000502', {COLUMN => 'event:severity', VERSIONS => 5}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
scan 'network_events', {LIMIT => 3}
scan 'network_events', {STARTROW => 'RTR-EDM-020#', STOPROW => 'RTR-EDM-020$'}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
scan 'network_events', {STARTROW => 'RTR-EDM-020#', STOPROW => 'RTR-EDM-020$'}
count 'network_events', {STARTROW => 'RTR-EDM-020#', STOPROW => 'RTR-EDM-020$'}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
count 'network_events', {FILTER => "SingleColumnValueFilter('event','severity',=,'binary:Critical')"}
scan 'network_events', {FILTER => "SingleColumnValueFilter('event','severity',=,'binary:Critical')", COLUMNS => ['device:id','event:type','event:timestamp'], LIMIT => 10}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
count 'network_events', {FILTER => "SingleColumnValueFilter('status','state',=,'binary:Open')"}
count 'network_events', {FILTER => "SingleColumnValueFilter('status','state',=,'binary:Investigating')"}
count 'network_events', {FILTER => "SingleColumnValueFilter('status','state',=,'binary:Open') OR SingleColumnValueFilter('status','state',=,'binary:Investigating')"}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
count 'network_events', {FILTER => "SingleColumnValueFilter('location','region',=,'binary:Eastern')"}
count 'network_events', {FILTER => "SingleColumnValueFilter('location','city',=,'binary:Ottawa')"}
scan 'network_events', {FILTER => "SingleColumnValueFilter('location','city',=,'binary:Ottawa') AND SingleColumnValueFilter('status','state',=,'binary:Open')", COLUMNS => ['device:id','event:type','event:severity','event:timestamp'], LIMIT => 10}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
count 'network_events', {FILTER => "SingleColumnValueFilter('event','error_code',=,'binary:NET-503')"}
scan 'network_events', {FILTER => "SingleColumnValueFilter('event','error_code',=,'binary:NET-503')", COLUMNS => ['device:id','event:timestamp','event:severity','location:city'], LIMIT => 15}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
count 'network_events', {FILTER => "SingleColumnValueFilter('device','type',=,'binary:Router')"}
count 'network_events', {STARTROW => 'RTR-', STOPROW => 'RTS-'}
count 'network_events', {STARTROW => 'RTR-EDM', STOPROW => 'RTR-EDN'}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
scan 'network_events', {STARTROW => 'RTR-EDM-020#9223370264531575807', STOPROW => 'RTR-EDM-020#9223370266950775807', COLUMNS => ['event:timestamp','event:type','event:severity']}
count 'network_events', {FILTER => "SingleColumnValueFilter('event','timestamp',>=,'binary:2026-02-01 00:00:00') AND SingleColumnValueFilter('event','timestamp',<=,'binary:2026-02-28 23:59:59')"}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
count 'network_events', {FILTER => "PrefixFilter('WLS-OTT-019#')"}
scan 'network_events', {FILTER => "PrefixFilter('WLS-OTT-019#')", COLUMNS => ['event:type','event:severity','event:timestamp'], LIMIT => 15}
count 'network_events', {FILTER => "PrefixFilter('WLS-')"}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
count 'network_events', {FILTER => "SingleColumnValueFilter('event','severity',=,'binary:Critical')"}
count 'network_events', {FILTER => "SingleColumnValueFilter('event','severity',=,'binary:Critical',true,true)"}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
scan 'network_events', {FILTER => "ValueFilter(=,'substring:connectivity')", LIMIT => 10}
count 'network_events', {FILTER => "ValueFilter(=,'substring:ConnectivityLoss')"}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
scan 'network_events', {COLUMNS => 'event', FILTER => "ColumnPrefixFilter('err')", LIMIT => 20}
count 'network_events', {FILTER => "ColumnPrefixFilter('err')"}
scan 'network_events', {FILTER => "MultipleColumnPrefixFilter('err','sev')", LIMIT => 10}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
count 'network_events', {FILTER => "RowFilter(=,'regexstring:^[A-Z]+-OTT-')"}
count 'network_events', {FILTER => "SingleColumnValueFilter('location','city',=,'binary:Ottawa')"}
scan 'network_events', {FILTER => "RowFilter(=,'substring:EVT-000018')"}
exit
HBASE_EOF

%sh
hbase shell -n <<'HBASE_EOF'
scan 'network_events', {FILTER => "SingleColumnValueFilter('event','severity',=,'binary:Critical') AND SingleColumnValueFilter('status','state',=,'binary:Open') AND SingleColumnValueFilter('location','region',=,'binary:Eastern')", COLUMNS => ['device:id','event:type','event:timestamp','location:city']}
scan 'network_events', {FILTER => "SingleColumnValueFilter('event','severity',=,'binary:Critical') AND PageFilter(10)", COLUMNS => ['device:id','event:timestamp']}
exit
HBASE_EOF
